def asset_src(filename, fallback="chicken.png"):
    """Return a Dash /assets path, using a fallback if a local asset file is missing.

    This keeps the homepage from showing broken image boxes if the real chicken
    photos have not been added to the assets folder yet. After adding new
    photos, restart the Dash app so this check updates.
    """
    assets_dir = Path(__file__).resolve().parent / "assets"
    requested = assets_dir / filename
    fallback_file = assets_dir / fallback

    if requested.exists():
        return f"/assets/{filename}"

    if fallback_file.exists():
        return f"/assets/{fallback}"

    return f"/assets/{filename}"

