county_names = sorted(county_coordinates.keys(), key=len, reverse=True)


def dropdown_tab(label, href, dropdown_items):
    return html.Div(
        className="dropdown",
        children=[
            dcc.Link(label, href=href, className="tab-button"),
            html.Div(
                className="dropdown-content",
                children=[
                    dcc.Link(item["label"], href=item["href"], className="dropdown-link")
                    for item in dropdown_items
                ],
            ),
        ],
    )


def find_column(df, possible_names):
    normalized = {
        str(col).lower().replace("\n", " ").replace("*", "").strip(): col
        for col in df.columns
    }

    for possible in possible_names:
        possible_lower = possible.lower()
        for normalized_name, original_col in normalized.items():
            if possible_lower in normalized_name:
                return original_col

    return None


def extract_county(value):
    text = str(value).replace("\xa0", " ").strip()

    for county in county_names:
        if text.lower().startswith(county.lower()):
            return county

    if text:
        return text.split()[0]

    return "Unknown"


def clean_birds_affected(value):
    text = str(value).replace(",", "").replace("\xa0", " ").strip()
    digits = "".join(char for char in text if char.isdigit())

    if digits == "":
        return 0

    return int(digits)


