def load_boah_data():
    try:
        tables = pd.read_html(BOAH_CASE_URL)

        selected_table = None

        for table in tables:
            table = table.copy()
            table.columns = [
                str(col).replace("\n", " ").replace("*", "").strip()
                for col in table.columns
            ]

            has_county = any("county" in str(col).lower() for col in table.columns)
            has_birds = any("birds" in str(col).lower() for col in table.columns)

            if has_county and has_birds:
                selected_table = table
                break

        if selected_table is None:
            return fallback_boah_data(), "Fallback BOAH sample data shown because the live table could not be parsed."

        df = selected_table.copy()

        county_col = find_column(df, ["county"])
        date_col = find_column(df, ["date confirmed", "date"])
        birds_col = find_column(df, ["birds affected", "birds"])
        operation_col = find_column(df, ["type of operation", "operation"])
        status_col = find_column(df, ["status"])
        type_col = find_column(df, ["type"])
        control_col = find_column(df, ["control area", "control"])
        surveillance_col = find_column(df, ["surveillance zone", "surveillance"])

        cleaned = pd.DataFrame()

        cleaned["Flock"] = df[county_col].astype(str) if county_col else "Unknown"
        cleaned["County"] = cleaned["Flock"].apply(extract_county)
        cleaned["Date Confirmed"] = df[date_col].astype(str) if date_col else "Unknown"
        cleaned["Birds Affected"] = df[birds_col].apply(clean_birds_affected) if birds_col else 0
        cleaned["Type of Operation"] = df[operation_col].astype(str) if operation_col else "Unknown"
        cleaned["Status"] = df[status_col].astype(str) if status_col else "Unknown"
        cleaned["Type"] = df[type_col].astype(str) if type_col else "Unknown"
        cleaned["Control Area"] = df[control_col].astype(str) if control_col else "Unknown"
        cleaned["Surveillance Zone"] = df[surveillance_col].astype(str) if surveillance_col else "Unknown"

        cleaned = cleaned[
            (cleaned["County"] != "Unknown")
            & (cleaned["County"].str.lower() != "nan")
            & (cleaned["Birds Affected"] >= 0)
        ]

        if cleaned.empty:
            return fallback_boah_data(), "Fallback BOAH sample data shown because the live table was empty after cleaning."

        return cleaned, "Live BOAH data loaded."

    except Exception as error:
        print("BOAH data could not be loaded:", error)
        return fallback_boah_data(), "Fallback BOAH sample data shown because the live BOAH page could not be loaded."


def make_boah_summary_card(boah_data):
    total_records = len(boah_data)
    total_birds = int(boah_data["Birds Affected"].sum())
    county_count = boah_data["County"].nunique()

    county_burden = (
        boah_data.groupby("County")["Birds Affected"]
        .sum()
        .sort_values(ascending=False)
    )

    top_county = county_burden.index[0] if not county_burden.empty else "Unknown"

    operation_counts = boah_data["Type of Operation"].value_counts()
    top_operation = operation_counts.index[0] if not operation_counts.empty else "Unknown"

    active_control_areas = int(
        boah_data["Control Area"].astype(str).str.contains("Active", case=False, na=False).sum()
    )

    if active_control_areas > 0:
        response_sentence = (
            f"The cleaned BOAH data include {active_control_areas:,} active control-area record(s), "
            "which suggests ongoing response activity and a need for strong farm-level biosecurity."
        )
    else:
        response_sentence = (
            "The cleaned BOAH data do not show active control-area language, but continued prevention and monitoring remain important."
        )

    return html.Div(
        style={
            **section_card_style,
            "marginBottom": "28px",
        },
        children=[
            html.H2(
                "Indiana BOAH Dashboard Summary",
                style={
                    "fontFamily": "Oswald, Arial, sans-serif",
                    "fontSize": "30px",
                    "color": DARK_RED,
                    "marginTop": "0",
                    "marginBottom": "14px",
                },
            ),
            html.P(
                f"BOAH data show {total_records:,} flock or premises records affecting "
                f"{total_birds:,} birds across {county_count:,} Indiana counties with BOAH records.",
                style={
                    "fontSize": "20px",
                    "lineHeight": "1.5",
                    "marginBottom": "12px",
                    "color": TEXT_DARK,
                },
            ),
            html.P(
                f"The highest bird burden in this dataset is in {top_county}, and the most common operation type is {top_operation}.",
                style={
                    "fontSize": "20px",
                    "lineHeight": "1.5",
                    "marginBottom": "12px",
                    "color": TEXT_DARK,
                },
            ),
            html.P(
                response_sentence,
                style={
                    "fontSize": "20px",
                    "lineHeight": "1.5",
                    "marginBottom": "12px",
                    "color": TEXT_DARK,
                },
            ),
            html.P(
                "The county count only includes Indiana counties that appear in the BOAH flock/premises table. Counties with no BOAH record are still included in the county risk map as zero BOAH-record counties.",
                style={
                    "fontSize": "18px",
                    "lineHeight": "1.45",
                    "margin": "0",
                    "color": TEXT_DARK,
                    "fontStyle": "italic",
                },
            ),
        ],
    )


