def county_to_slug(county_name):
    """Convert an Indiana county name into a simple URL slug."""
    return str(county_name).strip().lower().replace(" ", "-").replace(".", "")


def county_from_slug(slug):
    """Convert a URL slug back into the county name used by the risk data."""
    cleaned_slug = str(slug or "").strip().lower()
    for county_name in county_coordinates.keys():
        if county_to_slug(county_name) == cleaned_slug:
            return county_name
    return None


