def fetch_county_weather(county, latitude, longitude):
    """Fetch current county-level weather from Open-Meteo.

    This app uses weather as a contextual risk factor. Weather is not a
    diagnostic indicator of avian influenza, but cool, moist, wet, and windy
    conditions can be useful for an educational risk lens because they can
    affect environmental persistence and farm-level exposure conditions.
    """
    params = urlencode(
        {
            "latitude": latitude,
            "longitude": longitude,
            "current": "temperature_2m,relative_humidity_2m,precipitation,wind_speed_10m",
            "daily": "precipitation_probability_max",
            "temperature_unit": "fahrenheit",
            "wind_speed_unit": "mph",
            "precipitation_unit": "inch",
            "timezone": "America/Indiana/Indianapolis",
            "forecast_days": 1,
        }
    )
    url = f"{OPEN_METEO_BASE_URL}?{params}"

    try:
        with urlopen(url, timeout=5) as response:
            payload = json.loads(response.read().decode("utf-8"))

        current = payload.get("current", {}) or {}
        daily = payload.get("daily", {}) or {}
        probability_values = daily.get("precipitation_probability_max", []) or [None]

        return {
            "Temperature_F": current.get("temperature_2m"),
            "Humidity_Percent": current.get("relative_humidity_2m"),
            "Precipitation_In": current.get("precipitation"),
            "Wind_Mph": current.get("wind_speed_10m"),
            "Precip_Probability_Percent": probability_values[0],
            "Weather_Status": "Live weather loaded",
        }
    except Exception as error:
        print(f"Weather could not be loaded for {county}:", error)
        return {
            "Temperature_F": None,
            "Humidity_Percent": None,
            "Precipitation_In": None,
            "Wind_Mph": None,
            "Precip_Probability_Percent": None,
            "Weather_Status": "Weather unavailable",
        }



def unavailable_weather_record(status="Weather unavailable"):
    return {
        "Temperature_F": None,
        "Humidity_Percent": None,
        "Precipitation_In": None,
        "Wind_Mph": None,
        "Precip_Probability_Percent": None,
        "Weather_Status": status,
    }


def normalize_open_meteo_payload(payload):
    current = payload.get("current", {}) or {}
    daily = payload.get("daily", {}) or {}
    probability_values = daily.get("precipitation_probability_max", []) or [None]

    return {
        "Temperature_F": current.get("temperature_2m"),
        "Humidity_Percent": current.get("relative_humidity_2m"),
        "Precipitation_In": current.get("precipitation"),
        "Wind_Mph": current.get("wind_speed_10m"),
        "Precip_Probability_Percent": probability_values[0] if probability_values else None,
        "Weather_Status": "Live weather loaded",
    }


def fetch_weather_for_counties(county_frame, chunk_size=25):
    """Fetch live weather for many counties in Open-Meteo batches.

    Open-Meteo supports comma-separated latitude/longitude lists, so batching
    keeps the dashboard responsive while still giving each mapped county its
    own weather-based risk context. If a batch fails, those counties receive a
    transparent unavailable status rather than crashing the dashboard.
    """
    weather_by_county = {}
    records = county_frame[["County", "Latitude", "Longitude"]].to_dict("records")

    for start in range(0, len(records), chunk_size):
        chunk = records[start:start + chunk_size]
        latitudes = ",".join(f'{item["Latitude"]:.4f}' for item in chunk)
        longitudes = ",".join(f'{item["Longitude"]:.4f}' for item in chunk)

        params = urlencode(
            {
                "latitude": latitudes,
                "longitude": longitudes,
                "current": "temperature_2m,relative_humidity_2m,precipitation,wind_speed_10m",
                "daily": "precipitation_probability_max",
                "temperature_unit": "fahrenheit",
                "wind_speed_unit": "mph",
                "precipitation_unit": "inch",
                "timezone": "America/Indiana/Indianapolis",
                "forecast_days": 1,
            }
        )
        url = f"{OPEN_METEO_BASE_URL}?{params}"

        try:
            with urlopen(url, timeout=6) as response:
                payload = json.loads(response.read().decode("utf-8"))

            payloads = payload if isinstance(payload, list) else [payload]

            for item, county_payload in zip(chunk, payloads):
                weather_by_county[item["County"]] = normalize_open_meteo_payload(county_payload)

            if len(payloads) < len(chunk):
                for item in chunk[len(payloads):]:
                    weather_by_county[item["County"]] = unavailable_weather_record("Weather batch incomplete")

        except Exception as error:
            print("Weather batch could not be loaded:", error)
            for item in chunk:
                weather_by_county[item["County"]] = unavailable_weather_record("Weather unavailable")

    return weather_by_county


def migration_profile_for_county(county):
    """Return a transparent migration-exposure profile for each county.

    The county score is an educational proxy. It combines Indiana geography
    with national flyway context: Mississippi Flyway background, Great Lakes
    waterfowl movement, Central Flyway spill-in, Atlantic Flyway western-edge
    influence, Wabash/Ohio river corridors, and central agricultural exposure.
    """
    if county in NORTHERN_WETLAND_MIGRATION_COUNTIES:
        return {
            "Migration_Score": 28,
            "Migration_Band": "Higher",
            "Migration_Pattern": "Northern wetland and waterfowl movement zone",
            "National_Flyway_Context": "Great Lakes connector plus Mississippi Flyway background",
            "Migration_Short": "Great Lakes / northern wetland signal",
        }

    if county in RIVER_CORRIDOR_MIGRATION_COUNTIES:
        return {
            "Migration_Score": 24,
            "Migration_Band": "Elevated",
            "Migration_Pattern": "River-corridor waterfowl movement zone",
            "National_Flyway_Context": "Ohio River or Wabash River corridor linked to Mississippi Flyway movement",
            "Migration_Short": "River corridor signal",
        }

    if county in CENTRAL_AGRICULTURE_MIGRATION_COUNTIES:
        return {
            "Migration_Score": 18,
            "Migration_Band": "Moderate",
            "Migration_Pattern": "Central agricultural and farm-traffic zone",
            "National_Flyway_Context": "Interior agricultural stopover context within the Mississippi Flyway region",
            "Migration_Short": "Central agriculture signal",
        }

    return {
        "Migration_Score": 15,
        "Migration_Band": "Baseline",
        "Migration_Pattern": "Statewide Mississippi Flyway background exposure",
        "National_Flyway_Context": "Baseline Mississippi Flyway influence across Indiana",
        "Migration_Short": "Statewide flyway background",
    }


