                            html.P(migration_band, style={"fontSize": "18px", "fontWeight": "700", "margin": "4px 0 12px 0", "color": DARK_RED}),
                            html.P(migration_pattern, style={"fontSize": "17px", "lineHeight": "1.45", "margin": "0 0 12px 0", "color": TEXT_DARK}),
                            html.Div("National flyway context", style={"fontFamily": "Oswald, Arial, sans-serif", "fontSize": "15px", "fontWeight": "700", "letterSpacing": "0.5px", "color": BURNT_ORANGE, "textTransform": "uppercase"}),
                            html.P(flyway_context, style={"fontSize": "17px", "lineHeight": "1.45", "margin": "4px 0 0 0", "color": TEXT_DARK}),
