                            html.P(wild_bird_profile.get("habitat_label", "Migration habitat context unavailable"), style={"fontSize": "18px", "fontWeight": "700", "margin": "4px 0 12px 0", "color": DARK_RED}),
                            html.P(wild_bird_profile.get("county_note", "Wild-bird context unavailable."), style={"fontSize": "16px", "lineHeight": "1.45", "margin": "0 0 14px 0", "color": TEXT_DARK}),
