def live_research_download_data():
    """Build live export tables at the moment a user clicks download.

    The export uses the same BOAH cleaning, weather retrieval, migration
    categories, surrounding-county calculations, and risk-scoring logic that
    power the dashboard. Timestamp and source fields are added for scientists
    who want to document when the data were pulled.
    """
    boah_data, data_status = load_boah_data()
    risk_df = build_county_risk_dataframe(boah_data)
    downloaded_at = datetime.now().isoformat(timespec="seconds")

    boah_export = boah_data.copy()
    boah_export["Download_Timestamp"] = downloaded_at
    boah_export["BOAH_Data_Status"] = data_status
    boah_export["BOAH_Source_URL"] = BOAH_CASE_URL
    boah_export["Record_Unit"] = "BOAH flock/premises record, not individual infected bird"

    risk_export = risk_df.copy()
    risk_export["Download_Timestamp"] = downloaded_at
    risk_export["BOAH_Data_Status"] = data_status
    risk_export["BOAH_Source_URL"] = BOAH_CASE_URL
    risk_export["Weather_Source_URL"] = OPEN_METEO_SOURCE_URL
    risk_export["Risk_Score_Method"] = (
        "AUC-ready weighted evidence model on a 0-10 scale: direct BOAH evidence up to 4.0 points + "
        "surrounding counties evidence up to 1.5 points + migration/habitat evidence up to 2.0 points + "
        "weather persistence evidence up to 2.5 points. AUC is a validation metric; the score is AUC-ready "
        "but not a validated probability unless historical outcome labels are supplied."
    )

    return boah_export, risk_export, data_status, downloaded_at


