def dashboard_metric_card(label, value, style):
    if isinstance(value, (int, float)) and not isinstance(value, bool):
        display_value = f"{value:,}"
    else:
        display_value = str(value)

    return html.Div(
        style=style,
        children=[
            html.Div(label, style={"fontSize": "15px", "fontWeight": "700", "color": DARK_RED}),
            html.H1(display_value, style={"margin": "8px 0 0 0", "fontSize": "36px", "color": TEXT_DARK, "lineHeight": "1.1"}),
        ],
    )


