@app.callback(
    Output("page-content", "children"),
    Input("url", "pathname")
)
def display_page(pathname):
    if pathname and pathname.startswith("/county/"):
        return county_dashboard_page(pathname.split("/county/", 1)[1])
    if pathname == "/track-outbreak":
        return track_outbreak_page()
    elif pathname == "/learn-more":
        return learn_more_page()
    elif pathname == "/what-is-h5n1":
        return what_is_h5n1_page()
    elif pathname == "/history-spread":
        return history_spread_page()
    elif pathname == "/clades-evolution":
        return clades_evolution_page()
    elif pathname == "/prevention":
        return prevention_page()
    elif pathname == "/biosecurity-tips":
        return biosecurity_tips_page()
    elif pathname == "/farm-tips":
        return farm_tips_page()
    elif pathname == "/when-to-report":
        return when_to_report_page()
    elif pathname == "/contact":
        return contact_page()
    elif pathname == "/external-resources":
        return contact_page()
    elif pathname == "/email-team":
        return email_team_page()
    else:
        return home_page()


