@app.callback(
    Output("url", "pathname"),
    Input("risk-map", "clickData"),
    prevent_initial_call=True,
)
def open_county_dashboard_from_map_click(click_data):
    """Open a county-specific dashboard page when a county is clicked."""
    if not click_data or not click_data.get("points"):
        return no_update

    point = click_data["points"][0]
    clicked_county = point.get("location") or point.get("hovertext")

    if not clicked_county:
        return no_update

    return f"/county/{county_to_slug(clicked_county)}"


@app.callback(
    Output("county-hover-details", "children"),
    Output("risk-map", "figure"),
    Input("risk-county-dropdown", "value"),
    Input("risk-map", "clickData"),
    State("risk-map", "relayoutData"),
    State("risk-data-store", "data"),
)
def update_county_map_selection(selected_county, click_data, relayout_data, risk_records):
    """Open/update the selected-county dashboard without map hover popups.

    County hover popups are disabled because they blocked nearby counties. The
    map only changes when the user clicks a county or selects one from the
    dropdown. The current zoom and pan are preserved while the selected county
    is darkened and the county-specific dashboard updates below the map.
    """
    if not risk_records:
        return county_detail_panel(None), make_risk_map_figure([], None, get_preserved_map_view(relayout_data))

    valid_counties = {record.get("County") for record in risk_records}

    selected_for_map = selected_county if selected_county in valid_counties else risk_records[0].get("County")

    if ctx.triggered_id == "risk-map" and click_data and click_data.get("points"):
        point = click_data["points"][0]
        clicked_county = point.get("location") or point.get("hovertext")
        if clicked_county in valid_counties:
            selected_for_map = clicked_county

    matching = [record for record in risk_records if record.get("County") == selected_for_map]
    if not matching:
        matching = [risk_records[0]]
        selected_for_map = matching[0].get("County")

    updated_panel = county_detail_panel(matching[0])
    updated_map = make_risk_map_figure(
        risk_records,
        selected_county=selected_for_map,
        mapbox_view=get_preserved_map_view(relayout_data),
    )
    return updated_panel, updated_map


@app.callback(
    Output("progress-fill", "style"),
    Output("progress-text", "children"),
    Output("checklist-chicken", "src"),
    Output("chicken-message", "children"),
    Input("farmer-checklist", "value"),
)
def update_checklist_progress(checked_items):
    total_items = len(checklist_options)
    completed_items = len(checked_items)
    percent = int((completed_items / total_items) * 100)

    progress_style = {
        "height": "100%",
        "width": f"{percent}%",
        "backgroundColor": DARK_RED,
        "transition": "width 0.4s ease",
    }

    if percent == 100:
        chicken_src = "/assets/happychicken.png"
        message = "Checklist complete. Your flock is better protected."
    else:
        chicken_src = "/assets/sickchicken.png"
        message = "Complete the checklist to help protect your flock."

    return progress_style, f"{percent}% complete", chicken_src, message


